-- ── 1. The memo: transaction-local settings (no table, no DDL — usable from STABLE callers), gone at commit ────────────────
CREATE OR REPLACE FUNCTION public._fs_memo_get(p_key text)
RETURNS jsonb LANGUAGE sql STABLE SET search_path = pg_catalog, public AS $$
  SELECT nullif(current_setting('fs_memo.k' || md5(p_key), true), '')::jsonb;
$$;
CREATE OR REPLACE FUNCTION public._fs_memo_put(p_key text, p_body jsonb)
RETURNS void LANGUAGE sql VOLATILE SET search_path = pg_catalog, public AS $$
  SELECT set_config('fs_memo.k' || md5(p_key), p_body::text, true);
$$;
REVOKE ALL ON FUNCTION public._fs_memo_get(text) FROM PUBLIC, anon, authenticated, service_role;
